// Photo library and where each photo is used on the site.
// Sizes, categories and alt text live in photo-library.json, generated by `npm run photos`
// (web-sized files in public/photos; full originals in photos-originals/, not in git).
// This file only picks which photos go where;
// the dashboard will take that job over later.

import library from "./photo-library.json";

export type PhotoCategory =
  | "wedding"
  | "pre-wedding"
  | "post-wedding"
  | "haldi"
  | "programme"
  | "birthday"
  | "portrait"
  | "manipur"
  | "uncategorized";

export type Photo = {
  id: string;
  src: string;
  width: number;
  height: number;
  alt: string;
  category: PhotoCategory;
};

type LibraryEntry = { width: number; height: number; category: string; alt: string };
const entries = library as Record<string, LibraryEntry>;

/** Look up one photo by its file name in public/photos. */
export function getPhoto(file: string): Photo {
  const entry = entries[file];
  if (!entry) throw new Error(`Photo "${file}" is not in photo-library.json. Run \`npm run photos\`.`);
  return {
    id: file.replace(/\.\w+$/, "").replace(/\W+/g, "-").toLowerCase(),
    src: `/photos/${encodeURIComponent(file)}`,
    width: entry.width,
    height: entry.height,
    alt: entry.alt,
    category: entry.category as PhotoCategory,
  };
}

/** Every photo in the library, e.g. for the Work page. */
export const allPhotos: Photo[] = Object.keys(entries).map(getPhoto);

